window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-64edbed2791dcb82"]={"versions": [{"id": "FIG-64edbed2791dcb82", "releases": ["R4.0.3", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm im Rahmen der AUTOSAR Classic Platform Timing Extensions (System Timing View). Es visualisiert eine über Steuergerätegrenzen hinweg verlaufende Timing-Wirkkette (Timing Chain / Data Flow of Interest) auf Systemebene, bestehend aus software-interner Kommunikation, lokaler Inter-Komponenten-Kommunikation und fahrzeuginterner Netzwerkübertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst zwei Steuergeräte (<code>ECU 1</code>, <code>ECU 2</code>), angebunden an ein gemeinsames Bussystem (<code>Bus / Network</code>).</p>\n<ul class=\"fig-list\"><li><strong>ECU 1:</strong> Enthält zwei Software-Komponenten (<code>SW-C 1</code>, <code>SW-C 2</code>), eine Laufzeitumgebung (<code>RTE</code>) sowie den Basessoftware-Kommunikationsstack (<code>Communication Stack</code>). <code>SW-C 1</code> verfügt über einen R-Port (Empfangsport, Dreieck nach oben) und einen P-Port (Sendeport, Dreieck nach unten). <code>SW-C 2</code> besitzt ebenfalls einen R-Port und einen P-Port.\n</li><li><strong>ECU 2:</strong> Enthält zwei Software-Komponenten (<code>SW-C 3</code>, <code>SW-C 4</code>), eine <code>RTE</code> und den <code>Communication Stack</code>. <code>SW-C 3</code> besitzt einen R-Port und einen P-Port; <code>SW-C 4</code> verfügt über einen R-Port und einen P-Port.\n</li><li><strong>Schnittstellen:</strong> Ports sind als AUTOSAR-Portelemente am unteren Rand der Komponenten modelliert (Dreieck nach oben für Required/Input-Ports, Dreieck nach unten für Provided/Output-Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der hervorgehobene Datenfluss (<code>Data flow of interest</code>, rote Pfeillinie) beschreibt die Ende-zu-Ende-Verkettung über mehrere Teilstrecken:</p>\n<ol class=\"fig-list\"><li>Komponenteninterner Datenfluss in <code>SW-C 1</code> hin zu deren P-Port.\n</li><li>Intra-ECU-Kommunikation über die <code>RTE</code> von <code>ECU 1</code>: Weiterleitung vom P-Port der <code>SW-C 1</code> an den R-Port der <code>SW-C 2</code>.\n</li><li>Komponenteninterner Datenfluss innerhalb der <code>SW-C 2</code> vom R-Port zum P-Port.\n</li><li>Inter-ECU-Kommunikation: Vom P-Port der <code>SW-C 2</code> durch die <code>RTE</code> und den <code>Communication Stack</code> von <code>ECU 1</code>, über das Netzwerk (<code>Bus / Network</code>) zu <code>ECU 2</code>, dort durch den <code>Communication Stack</code> und die <code>RTE</code> an den R-Port von <code>SW-C 3</code>.\n</li><li>Intra-ECU-Kommunikation über die <code>RTE</code> von <code>ECU 2</code>: Vom P-Port der <code>SW-C 3</code> zum R-Port der <code>SW-C 4</code>.\n</li><li>Komponenteninterner Datenfluss in <code>SW-C 4</code> vom R-Port in die Komponentenlogik.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzbeispiel für die Definition von <code>TimingExtension</code> auf Systemebene (System Timing). Die dargestellte Kette bildet eine zusammengesetzte Timing Chain (<code>TimingChain</code>), die hierarchisch aus Teilketten (<code>EventChain</code> / <code>LatencyTimingConstraint</code>) zusammengesetzt werden kann: Execution Timings/Inter-Runnable-Flows innerhalb der SW-Cs, RTE-Laufzeiten auf der ECU und Communication Latencies (Frame-/Signalübertragung) über den Bus.</p>"}, {"id": "FIG-a33c79351323bcf3", "releases": ["R4.1.3", "R4.3.1", "R19-11", "R20-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm im Rahmen der AUTOSAR Classic Platform Timing Extensions (System Timing View). Es visualisiert eine über Steuergerätegrenzen hinweg verlaufende Timing-Wirkkette (Timing Chain / Data Flow of Interest) auf Systemebene, bestehend aus software-interner Kommunikation, lokaler Inter-Komponenten-Kommunikation und fahrzeuginterner Netzwerkübertragung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System umfasst zwei Steuergeräte (<code>ECU 1</code>, <code>ECU 2</code>), angebunden an ein gemeinsames Bussystem (<code>Bus / Network</code>).</p>\n<ul class=\"fig-list\"><li><strong>ECU 1:</strong> Enthält zwei Software-Komponenten (<code>SW-C 1</code>, <code>SW-C 2</code>), eine Laufzeitumgebung (<code>RTE</code>) sowie den Basessoftware-Kommunikationsstack (<code>Communication Stack</code>). <code>SW-C 1</code> verfügt über einen R-Port (Empfangsport, Dreieck nach oben) und einen P-Port (Sendeport, Dreieck nach unten). <code>SW-C 2</code> besitzt ebenfalls einen R-Port und einen P-Port.\n</li><li><strong>ECU 2:</strong> Enthält zwei Software-Komponenten (<code>SW-C 3</code>, <code>SW-C 4</code>), eine <code>RTE</code> und den <code>Communication Stack</code>. <code>SW-C 3</code> besitzt einen R-Port und einen P-Port; <code>SW-C 4</code> verfügt über einen R-Port und einen P-Port.\n</li><li><strong>Schnittstellen:</strong> Ports sind als AUTOSAR-Portelemente am unteren Rand der Komponenten modelliert (Dreieck nach oben für Required/Input-Ports, Dreieck nach unten für Provided/Output-Ports).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der hervorgehobene Datenfluss (<code>Data flow of interest</code>, rote Pfeillinie) beschreibt die Ende-zu-Ende-Verkettung über mehrere Teilstrecken:</p>\n<ol class=\"fig-list\"><li>Komponenteninterner Datenfluss in <code>SW-C 1</code> hin zu deren P-Port.\n</li><li>Intra-ECU-Kommunikation über die <code>RTE</code> von <code>ECU 1</code>: Weiterleitung vom P-Port der <code>SW-C 1</code> an den R-Port der <code>SW-C 2</code>.\n</li><li>Komponenteninterner Datenfluss innerhalb der <code>SW-C 2</code> vom R-Port zum P-Port.\n</li><li>Inter-ECU-Kommunikation: Vom P-Port der <code>SW-C 2</code> durch die <code>RTE</code> und den <code>Communication Stack</code> von <code>ECU 1</code>, über das Netzwerk (<code>Bus / Network</code>) zu <code>ECU 2</code>, dort durch den <code>Communication Stack</code> und die <code>RTE</code> an den R-Port von <code>SW-C 3</code>.\n</li><li>Intra-ECU-Kommunikation über die <code>RTE</code> von <code>ECU 2</code>: Vom P-Port der <code>SW-C 3</code> zum R-Port der <code>SW-C 4</code>.\n</li><li>Komponenteninterner Datenfluss in <code>SW-C 4</code> vom R-Port in die Komponentenlogik.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm dient als Referenzbeispiel für die Definition von <code>TimingExtension</code> auf Systemebene (System Timing). Die dargestellte Kette bildet eine zusammengesetzte Timing Chain (<code>TimingChain</code>), die hierarchisch aus Teilketten (<code>EventChain</code> / <code>LatencyTimingConstraint</code>) zusammengesetzt werden kann: Execution Timings/Inter-Runnable-Flows innerhalb der SW-Cs, RTE-Laufzeiten auf der ECU und Communication Latencies (Frame-/Signalübertragung) über den Bus.</p>"}, {"id": "FIG-5e98bf2201bc4ad6", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Datenflussdiagramm im Rahmen der AUTOSAR Adaptive Platform Timing Extensions (System Timing View). Es visualisiert eine über Plattform-/Maschinengrenzen hinweg verlaufende Timing-Wirkkette (Timing Chain / Data Flow of Interest) auf Basis service-orientierter Kommunikation (SOME/IP bzw. <code>ara::com</code>) zwischen Adaptive Applications.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das System besteht aus zwei Maschinen (<code>Machine 1</code>, <code>Machine 2</code>), verbunden über ein physikalisches Netzwerk (<code>Bus / Network</code>).</p>\n<ul class=\"fig-list\"><li><strong>Machine 1:</strong> Beherbergt zwei Adaptive Application Software Components (<code>Swc1</code>, <code>Swc2</code>) und die Kommunikations-Middleware <code>ara::com</code>. Jede Komponente besitzt zwei generische Service-Ports (<code>Provided/Required Service Port</code>, dargestellt als quadratische Boxen am unteren Komponentenrand).\n</li><li><strong>Machine 2:</strong> Beherbergt zwei Adaptive Application Software Components (<code>Swc3</code>, <code>Swc4</code>) sowie <code>ara::com</code>. Beide Komponenten verfügen über je zwei Service-Ports (<code>Provided/Required Service Port</code>).\n</li><li><strong>Schnittstellen:</strong> Kommunikation erfolgt service-orientiert über <code>ara::com</code> und die Service-Ports; separate hardwarenahe Communication-Stack-Blöcke der Classic-BSW entfallen in der Darstellung.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Gesamtdatenfluss gliedert sich in interne und externe Abschnitte:</p>\n<ol class=\"fig-list\"><li>Interner Datenfluss (<code>Internal data flow of interest</code>, grauer Pfeil) innerhalb von <code>Swc1</code> zum Service-Port.\n</li><li>Lokale Inter-Prozess-/Inter-Komponenten-Kommunikation (<code>Data flow of interest</code>, rote Pfeillinie) über <code>ara::com</code> auf <code>Machine 1</code> vom Service-Port der <code>Swc1</code> zum Eingangs-Service-Port der <code>Swc2</code>.\n</li><li>Interner Komponentenfluss (rote Pfeillinie) durch <code>Swc2</code> zum Ausgangs-Service-Port.\n</li><li>Netzübergreifende Service-Kommunikation: Vom Service-Port der <code>Swc2</code> über <code>ara::com</code>, das Netzwerk (<code>Bus / Network</code>) und <code>ara::com</code> auf <code>Machine 2</code> an den Ziel-Service-Port von <code>Swc3</code>.\n</li><li>Lokale Kommunikation über <code>ara::com</code> auf <code>Machine 2</code> vom Ausgangs-Service-Port der <code>Swc3</code> zum Service-Port der <code>Swc4</code>.\n</li><li>Interner Datenfluss (<code>Internal data flow of interest</code>, grauer Pfeil) innerhalb von <code>Swc4</code>.\n</li></ol>\n<p class=\"fig-p\">Die Legende weist zudem auf virtuelle Verbindungen hin, die während Service Discovery und Subscription aufgebaut werden (<code>Virtual connection created/established during service discovery and subscription</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht die Spezifikation von End-to-End-Latenzen und Timing-Constraints in service-orientierten Architekturen (Adaptive Platform). Eine Timing-Kette setzt sich aus internen Ausführungszeiten (<code>Internal data flow</code>), lokalen Middleware-Laufzeiten (<code>ara::com</code> IPC) und netzwerkweiten Service-Roundtrip-/Übertragungszeiten zusammen. Bei der Timing-Analyse sind dynamische Aspekte wie Service Discovery und Subscription-Zustände relevant.</p>"}], "trans": [{"from": "FIG-64edbed2791dcb82", "to": "FIG-a33c79351323bcf3", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a33c79351323bcf3", "to": "FIG-64edbed2791dcb82", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a33c79351323bcf3", "to": "FIG-5e98bf2201bc4ad6", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Architekturkontext von AUTOSAR Classic Platform auf AUTOSAR Adaptive Platform umgestellt: <code>ECU 1</code> und <code>ECU 2</code> durch <code>Machine 1</code> und <code>Machine 2</code> ersetzt.\n</li><li>Kommunikations- und Middleware-Schicht von <code>RTE</code> und <code>Communication Stack</code> auf <code>ara::com</code> umgestellt (<code>Communication Stack</code>-Blöcke entfallen).\n</li><li>Komponenten von Classic <code>SW-C 1</code> bis <code>SW-C 4</code> auf <code>Adaptive Application Software Component</code> (<code>Swc1</code> bis <code>Swc4</code>) umgestellt.\n</li><li>Port-Modell von richtungsgebundenen Classic AUTOSAR Ports (R-Port mit Dreieck nach oben, P-Port mit Dreieck nach unten) auf Service-orientierte Schnittstellen (<code>Provided/Required Service Port</code>, dargestellt als neutrale quadratische Port-Symbole) geändert.\n</li><li>Legende erweitert um <code>Internal data flow of interest</code> (grauer Pfeil), <code>Provided/Required Service Port</code> (Quadrat), <code>Adaptive Application Software Component</code> (hellblauer Kasten) und <code>Virtual connection created/established during service discovery and subscription</code> (gestrichelte Linie).\n</li><li>Darstellung des internen Datenflusses in der initialen Quellkomponente (<code>Swc1</code>) und der finalen Zielkomponente (<code>Swc4</code>) von roten Pfeilen auf graue Pfeile (<code>Internal data flow of interest</code>) geändert.\n</li></ul>"}]};
